using System.Collections.Generic; using System.Linq; namespace RadeonSoftwareSlimmer.Optimize; public static class GeneralTweakCatalog { public static IReadOnlyList<SystemTweak> Defined {get;}=TweakCatalog.All.Concat(MultimediaTweakCatalog.All).ToList(); public static IReadOnlyList<SystemTweak> All=>Defined; public static IEnumerable<SystemTweak> Recommended=>All.Where(IsRecommended); public static bool IsRecommended(SystemTweak t)=>t.Id.StartsWith("gamedvr-")||t.Id=="appcapture-off"; }